-- Create "galleries" table
CREATE TABLE "galleries" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "preview_small_style" character varying NOT NULL DEFAULT 'gallery_thumbnail', "preview_medium_style" character varying NOT NULL DEFAULT 'gallery_medium', "title" character varying NULL, "description" text NULL, "weight" bigint NULL DEFAULT 0, "status" boolean NULL DEFAULT true, "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "galleries_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "gallery_status" to table: "galleries"
CREATE INDEX "gallery_status" ON "galleries" ("status");
-- Create index "gallery_nid_status_weight" to table: "galleries"
CREATE INDEX "gallery_nid_status_weight" ON "galleries" ("nid", "status", "weight");
-- Create "gallery_content_types" table
CREATE TABLE "gallery_content_types" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "default_enabled" boolean NOT NULL DEFAULT false, "picture_field" character varying NOT NULL DEFAULT '', "content_type_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "gallery_content_types_content_types_content_type" FOREIGN KEY ("content_type_id") REFERENCES "content_types" ("id") ON DELETE CASCADE);
-- Create index "gallerycontenttype_content_type_id" to table: "gallery_content_types"
CREATE UNIQUE INDEX "gallerycontenttype_content_type_id" ON "gallery_content_types" ("content_type_id");
-- Create "gallery_items" table
CREATE TABLE "gallery_items" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "title" character varying NULL, "description" text NULL, "weight" bigint NULL DEFAULT 0, "is_cover" boolean NOT NULL DEFAULT false, "created_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP), "gallery_id" bigint NOT NULL, "fid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "gallery_items_galleries_gallery" FOREIGN KEY ("gallery_id") REFERENCES "galleries" ("id") ON DELETE CASCADE, CONSTRAINT "gallery_items_files_file" FOREIGN KEY ("fid") REFERENCES "files" ("id") ON DELETE CASCADE);
-- Create index "galleryitem_gallery_id_fid" to table: "gallery_items"
CREATE UNIQUE INDEX "galleryitem_gallery_id_fid" ON "gallery_items" ("gallery_id", "fid");
-- Create index "galleryitem_gallery_id_weight" to table: "gallery_items"
CREATE INDEX "galleryitem_gallery_id_weight" ON "gallery_items" ("gallery_id", "weight");
-- Create index "galleryitem_gallery_id_is_cover" to table: "gallery_items"
CREATE INDEX "galleryitem_gallery_id_is_cover" ON "gallery_items" ("gallery_id", "is_cover");
-- Create index "galleryitem_fid" to table: "gallery_items"
CREATE INDEX "galleryitem_fid" ON "gallery_items" ("fid");
-- Create "gallery_nodes" table
CREATE TABLE "gallery_nodes" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "gallery_nodes_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "gallerynode_nid" to table: "gallery_nodes"
CREATE UNIQUE INDEX "gallerynode_nid" ON "gallery_nodes" ("nid");
